// Las únicas «compuertas»: cada una opera sobre UN bit (0 o 1)
const xor = (a, b) => a ^ b;
const and = (a, b) => a & b;
const or  = (a, b) => a | b;

// Semisumador: dos compuertas
function semisumador(a, b) {
  return { suma: xor(a, b), acarreo: and(a, b) };
}

// Sumador completo: dos semisumadores y una OR
function sumadorCompleto(a, b, cin) {
  const h1 = semisumador(a, b);
  const h2 = semisumador(h1.suma, cin);
  return { suma: h2.suma, acarreo: or(h1.acarreo, h2.acarreo) };
}

// Los «cables de entrada»: parten un número en 8 bits (posición 0 = el de más a la derecha)
const aBits = n => Array.from({ length: 8 }, (_, i) => (n >> i) & 1);

// Cadena de 8 sumadores: el acarreo de salida de uno es el acarreo de entrada del siguiente
function sumar8(a, b, cin = 0) {
  const A = aBits(a), B = aBits(b);
  const bits = [], entra = [];
  let c = cin;
  for (let i = 0; i < 8; i++) {
    entra.push(c);                          // acarreo que entra a la columna i
    const r = sumadorCompleto(A[i], B[i], c);
    bits.push(r.suma);
    c = r.acarreo;
  }
  return {
    suma: bits.reduce((n, bit, i) => n + bit * 2 ** i, 0),
    binario: bits.slice().reverse().join(""),
    entra: entra.slice().reverse().join(""),  // de la columna 7 a la 0, como se escribe el número
    acarreoFinal: c
  };
}

// Probá tus propias sumas: agregá pares a esta lista
const casos = [[45, 27], [255, 1], [170, 85]];
for (const [a, b] of casos) {
  const r = sumar8(a, b);
  console.log(`${a} + ${b} = ${r.suma}  (${r.binario})  acarreo final: ${r.acarreoFinal}  acarreos que entran: ${r.entra}`);
}

const xor = (a, b) => a ^ b, and = (a, b) => a & b, or = (a, b) => a | b;
const aBits = n => Array.from({ length: 8 }, (_, i) => (n >> i) & 1);
const aNumero = bits => bits.reduce((n, bit, i) => n + bit * 2 ** i, 0);

// Referencia: la cadena en cascada de hoy (cada acarreo espera al anterior)
function enCascada(A, B, c0) {
  const S = []; let c = c0;
  for (let i = 0; i < 8; i++) {
    const x = xor(A[i], B[i]);
    S.push(xor(x, c));
    c = or(and(A[i], B[i]), and(x, c));
  }
  return { suma: S, acarreoFinal: c };
}

// Con adelanto: todos los acarreos salen de «genera» (g), «propaga» (p) y el acarreo inicial
const todos = (v, desde, hasta) => v.slice(desde, hasta + 1).reduce(and, 1); // AND de varios bits
function conAdelanto(A, B, c0) {
  const g = A.map((a, i) => and(a, B[i]));
  const p = A.map((a, i) => xor(a, B[i]));
  const c = [c0];
  for (let i = 0; i < 8; i++) {
    let acarreo = and(c0, todos(p, 0, i));                 // el acarreo inicial cruza hasta la columna i
    for (let j = 0; j <= i; j++) {
      acarreo = or(acarreo, and(g[j], todos(p, j + 1, i))); // la columna j genera y las siguientes propagan
    }
    c.push(acarreo);                                       // c[i+1] no esperó a c[i]
  }
  return { suma: p.map((x, i) => xor(x, c[i])), acarreoFinal: c[8] };
}

// Comprobación exhaustiva: 256 × 256 sumas, con acarreo inicial 0 y 1
let iguales = 0, total = 0;
for (let a = 0; a < 256; a++) for (let b = 0; b < 256; b++) for (const c0 of [0, 1]) {
  const r1 = enCascada(aBits(a), aBits(b), c0), r2 = conAdelanto(aBits(a), aBits(b), c0);
  total++;
  if (aNumero(r1.suma) === aNumero(r2.suma) && r1.acarreoFinal === r2.acarreoFinal) iguales++;
}
console.log(`coinciden ${iguales} de ${total} sumas`);

const xor = (a, b) => a ^ b, and = (a, b) => a & b, or = (a, b) => a | b;
const aBits = n => Array.from({ length: 8 }, (_, i) => (n >> i) & 1);

function sumadorCompleto(a, b, cin) {
  const x = xor(a, b);
  return { suma: xor(x, cin), acarreo: or(and(a, b), and(x, cin)) };
}

// Sumador/restador: con restar = 0 suma; con restar = 1 resta (a − b = a + NOT b + 1)
function sumarRestar(a, b, restar) {
  const A = aBits(a), B = aBits(b);
  const bits = [], entra = [];
  let c = restar;                              // el «+ 1» entra como acarreo del primer sumador
  for (let i = 0; i < 8; i++) {
    entra.push(c);
    const bi = xor(B[i], restar);              // XOR con 1 invierte el bit; con 0 lo deja igual
    const r = sumadorCompleto(A[i], bi, c);
    bits.push(r.suma);
    c = r.acarreo;
  }
  const antesDelUltimo = entra[7];             // acarreo que entra al sumador del bit más significativo
  return {
    suma: bits.reduce((n, bit, i) => n + bit * 2 ** i, 0),
    binario: bits.slice().reverse().join(""),
    acarreoFinal: c,
    desbordaConSigno: xor(antesDelUltimo, c)   // regla: el acarreo que entra y el que sale difieren
  };
}

for (const [a, b] of [[100, 37], [45, 27], [27, 45]]) {
  const r = sumarRestar(a, b, 1);
  console.log(`${a} - ${b} = ${r.suma}  (${r.binario})  acarreo final: ${r.acarreoFinal}`);
}
console.log("--- el mismo circuito, sumando ---");
for (const [a, b] of [[100, 37], [127, 1], [255, 1]]) {
  const r = sumarRestar(a, b, 0);
  console.log(`${a} + ${b} -> ${r.suma}  acarreo final: ${r.acarreoFinal}  desborda con signo: ${r.desbordaConSigno}`);
}
